"""Complaint PDF and TXT generation."""
import os
import tempfile
from datetime import datetime, timezone
from pathlib import Path

from backend.analysis.rules import RULES

_DISCLAIMER = (
    "DISCLAIMER: This report is generated by an automated AI system (DarkGuard AI) "
    "for informational purposes only. It does not constitute legal advice. "
    "Please consult a consumer advocate or legal professional for formal complaints."
)

_NEXT_STEPS = (
    "NEXT STEPS:\n"
    "• National Consumer Helpline: 1915\n"
    "• Online: https://consumerhelpline.gov.in\n"
    "• E-Daakhil (online consumer forum): https://edaakhil.nic.in\n"
    "• State Consumer Disputes Redressal Commission (SCDRC)\n"
)


def _fmt_date() -> str:
    return datetime.now(timezone.utc).strftime("%d %B %Y, %H:%M UTC")


def generate_txt(
    audit_id: str,
    platform: str,
    result: dict,
    score: float,
    is_simulated: bool,
) -> str:
    trust_score = result.get("trust_score", {})
    score_val = trust_score.get("score", score or 0)
    patterns = result.get("patterns", [])

    lines = [
        "=" * 70,
        "DARKGUARD AI – CONSUMER COMPLAINT SUMMARY",
        "=" * 70,
        f"Platform:    {platform.title()}",
        f"Audit ID:    {audit_id}",
        f"Date:        {_fmt_date()}",
        f"Trust Score: {score_val}/10  ({trust_score.get('label', '')})",
        f"Mode:        {'⚠ SIMULATED DEMO RESULTS: AI not configured' if is_simulated else 'AI Analysis'}",
        "",
    ]

    if is_simulated:
        lines.append("⚠ WARNING: SIMULATED DEMO RESULTS: AI not configured. ⚠")
        lines.append("Results below are based on rule-based analysis only and are NOT real AI output.")
        lines.append("")

    lines.append("DARK PATTERN FINDINGS")
    lines.append("-" * 70)

    for p in patterns:
        rule = RULES.get(p.get("pattern_key", ""), {})
        status = p.get("status", "CLEAR")
        status_sym = {"FOUND": "✗ FOUND", "WARNING": "⚠ WARNING", "CLEAR": "✓ CLEAR"}.get(status, status)
        lines.append(f"\n[{status_sym}] {p.get('pattern_name', '')}")
        lines.append(f"  {p.get('explanation', '')}")
        evidence_list = p.get("evidence", [])
        if evidence_list:
            lines.append("  Evidence:")
            for ev in evidence_list:
                lines.append(f"    • Screenshot {ev.get('screenshot', '?')}: \"{ev.get('text', '')}\"")
        lines.append(f"  Rule: {p.get('ccpa_reference', rule.get('clause', ''))}")
        lines.append(f"  ({rule.get('ccpa_guideline', 'CCPA Dark Patterns Guidelines, 2023')})")

    lines.append("")
    lines.append("-" * 70)
    lines.append(_NEXT_STEPS)
    lines.append("-" * 70)
    lines.append(_DISCLAIMER)
    lines.append("=" * 70)
    return "\n".join(lines)


def generate_pdf(
    audit_id: str,
    platform: str,
    result: dict,
    score: float,
    is_simulated: bool,
) -> str:
    """Generate PDF and return the file path."""
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib import colors
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.units import cm
        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, HRFlowable, Table, TableStyle
        from reportlab.lib.enums import TA_LEFT, TA_CENTER

        trust_score = result.get("trust_score", {})
        score_val = trust_score.get("score", score or 0)
        patterns = result.get("patterns", [])

        tmp = tempfile.NamedTemporaryFile(suffix=".pdf", delete=False, prefix="darkguard_")
        tmp.close()

        doc = SimpleDocTemplate(
            tmp.name,
            pagesize=A4,
            rightMargin=2 * cm,
            leftMargin=2 * cm,
            topMargin=2 * cm,
            bottomMargin=2 * cm,
        )
        styles = getSampleStyleSheet()
        DG_GREEN = colors.HexColor("#14594D")
        DG_RED = colors.HexColor("#D32F2F")
        DG_ORANGE = colors.HexColor("#F57C00")

        title_style = ParagraphStyle("Title", parent=styles["Heading1"], textColor=DG_GREEN, fontSize=18, spaceAfter=6)
        h2_style = ParagraphStyle("H2", parent=styles["Heading2"], textColor=DG_GREEN, fontSize=13, spaceBefore=12, spaceAfter=4)
        body_style = ParagraphStyle("Body", parent=styles["Normal"], fontSize=10, spaceAfter=4)
        small_style = ParagraphStyle("Small", parent=styles["Normal"], fontSize=8, textColor=colors.grey)
        warn_style = ParagraphStyle("Warn", parent=styles["Normal"], fontSize=10, textColor=DG_ORANGE)
        found_style = ParagraphStyle("Found", parent=styles["Normal"], fontSize=10, textColor=DG_RED)

        story = []
        story.append(Paragraph("DarkGuard AI – Consumer Complaint Summary", title_style))
        story.append(HRFlowable(width="100%", color=DG_GREEN, spaceAfter=8))

        meta = [
            ["Platform:", platform.title()],
            ["Audit ID:", audit_id],
            ["Date:", _fmt_date()],
            ["Trust Score:", f"{score_val}/10  ({trust_score.get('label', '')})"],
            ["Mode:", "⚠ SIMULATED DEMO – AI not configured" if is_simulated else "AI Analysis"],
        ]
        t = Table(meta, colWidths=[3.5 * cm, 13 * cm])
        t.setStyle(TableStyle([
            ("FONTNAME", (0, 0), (-1, -1), "Helvetica"),
            ("FONTSIZE", (0, 0), (-1, -1), 10),
            ("FONTNAME", (0, 0), (0, -1), "Helvetica-Bold"),
            ("TEXTCOLOR", (0, 0), (0, -1), DG_GREEN),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
        ]))
        story.append(t)
        story.append(Spacer(1, 0.4 * cm))

        if is_simulated:
            story.append(Paragraph("⚠ SIMULATED DEMO RESULTS: AI not configured. Results are rule-based only and NOT real AI output.", warn_style))
            story.append(Spacer(1, 0.3 * cm))

        story.append(Paragraph("Dark Pattern Findings", h2_style))
        story.append(HRFlowable(width="100%", color=colors.lightgrey, spaceAfter=6))

        for p in patterns:
            rule = RULES.get(p.get("pattern_key", ""), {})
            status = p.get("status", "CLEAR")
            status_label = {"FOUND": "✗ FOUND", "WARNING": "⚠ WARNING", "CLEAR": "✓ CLEAR"}.get(status, status)
            st = found_style if status == "FOUND" else warn_style if status == "WARNING" else body_style
            story.append(Paragraph(f"[{status_label}]  {p.get('pattern_name', '')}", st))
            story.append(Paragraph(p.get("explanation", ""), body_style))
            evidence_list = p.get("evidence", [])
            for ev in evidence_list:
                story.append(Paragraph(f"• Screenshot {ev.get('screenshot', '?')}: \"{ev.get('text', '')}\"", small_style))
            ref = p.get("ccpa_reference") or rule.get("clause", "CCPA Dark Patterns Guidelines, 2023")
            story.append(Paragraph(f"Rule: {ref}", small_style))
            story.append(Spacer(1, 0.3 * cm))

        story.append(HRFlowable(width="100%", color=colors.lightgrey, spaceAfter=6))
        story.append(Paragraph("Next Steps", h2_style))
        for line in _NEXT_STEPS.split("\n")[1:]:
            if line.strip():
                story.append(Paragraph(line.strip(), body_style))
        story.append(Spacer(1, 0.3 * cm))
        story.append(Paragraph(_DISCLAIMER, small_style))

        doc.build(story)
        return tmp.name

    except ImportError:
        # Fallback: write a plain text file and return it
        txt = generate_txt(audit_id, platform, result, score, is_simulated)
        tmp = tempfile.NamedTemporaryFile(suffix=".pdf", delete=False, prefix="darkguard_", mode="w", encoding="utf-8")
        tmp.write(txt)
        tmp.close()
        return tmp.name
